python3 -c '
import sys, json

args = [a for a in sys.argv[1:] if a and a not in ["undefined", "None", "null", "NoneType"] and not a.startswith("${")]
content = " ".join(args).strip() if args else ""

if not content:
    content = "No content provided to display."

try:
    data = json.loads(content)
    if isinstance(data, (dict, list)):
        print(json.dumps(data))
    else:
        print(json.dumps({"content": str(data)}))
except Exception:
    print(json.dumps({"content": content}))
' "${answer1}"
